  if(q.type==='order'){
   await page.locator(`[data-pick="${q.order.at(-1)}"]`).click();await page.locator('[data-remove="0"]').click();
   for(const id of q.order)await page.locator(`[data-pick="${id}"]`).click();await page.locator('#check').click();
  }
