 assert.deepEqual(errors,[]);console.log('PASS: 44 questions, wrong-answer retry, hint scoring, ordering undo, persistence, due review, mobile layout, zero browser errors');
 }finally{await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});

